function calcSMA(values, period) {
  const res = new Array(values.length).fill(null);
  if (values.length < period) return res;
  let sum = 0;
  for (let i = 0; i < values.length; i++) {
    sum += values[i];
    if (i >= period) sum -= values[i - period];
    if (i >= period - 1) res[i] = sum / period;
  }
  return res;
}
function calcEMA(values, period) {
  const res = new Array(values.length).fill(null);
  if (values.length === 0) return res;
  const k = 2 / (period + 1);
  let ema = values[0];
  res[0] = ema;
  for (let i = 1; i < values.length; i++) {
    ema = values[i] * k + ema * (1 - k);
    res[i] = ema;
  }
  return res;
}
function calcRSI(values, period = 14) {
  const res = new Array(values.length).fill(null);
  if (values.length <= period) return res;
  let avgGain = 0;
  let avgLoss = 0;
  for (let i = 1; i <= period; i++) {
    const diff = values[i] - values[i - 1];
    if (diff > 0) avgGain += diff;
    else avgLoss -= diff;
  }
  avgGain /= period;
  avgLoss /= period;
  res[period] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
  for (let i = period + 1; i < values.length; i++) {
    const diff = values[i] - values[i - 1];
    const gain = diff > 0 ? diff : 0;
    const loss = diff < 0 ? -diff : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
    res[i] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
  }
  return res;
}
function calcMACD(values, fast = 12, slow = 26, signalPeriod = 9) {
  const len = values.length;
  const macdLine = new Array(len).fill(null);
  const signalLine = new Array(len).fill(null);
  const histogram = new Array(len).fill(null);
  if (len < slow) return { macdLine, signalLine, histogram };
  const emaFast = calcEMA(values, fast);
  const emaSlow = calcEMA(values, slow);
  const validMacd = [];
  const validIdx = [];
  for (let i = 0; i < len; i++) {
    if (emaFast[i] !== null && emaSlow[i] !== null && i >= slow - 1) {
      const m = emaFast[i] - emaSlow[i];
      macdLine[i] = m;
      validMacd.push(m);
      validIdx.push(i);
    }
  }
  if (validMacd.length > 0) {
    const sigEma = calcEMA(validMacd, signalPeriod);
    for (let j = 0; j < validMacd.length; j++) {
      const idx = validIdx[j];
      signalLine[idx] = sigEma[j];
      histogram[idx] = macdLine[idx] - sigEma[j];
    }
  }
  return { macdLine, signalLine, histogram };
}
function calcBollingerBands(values, period = 20, stdMult = 2) {
  const len = values.length;
  const middle = calcSMA(values, period);
  const upper = new Array(len).fill(null);
  const lower = new Array(len).fill(null);
  for (let i = period - 1; i < len; i++) {
    const mean = middle[i];
    let variance = 0;
    for (let j = i - period + 1; j <= i; j++) {
      const diff = values[j] - mean;
      variance += diff * diff;
    }
    const std = Math.sqrt(variance / period);
    upper[i] = mean + stdMult * std;
    lower[i] = mean - stdMult * std;
  }
  return { upper, middle, lower };
}
function calcATR(candles, period = 14) {
  const len = candles.length;
  const res = new Array(len).fill(null);
  if (len < 2) return res;
  const tr = [candles[0].high - candles[0].low];
  for (let i = 1; i < len; i++) {
    const c = candles[i];
    const prevClose = candles[i - 1].close;
    tr.push(
      Math.max(
        c.high - c.low,
        Math.abs(c.high - prevClose),
        Math.abs(c.low - prevClose)
      )
    );
  }
  if (len <= period) return res;
  let atr = 0;
  for (let i = 0; i < period; i++) atr += tr[i];
  atr /= period;
  res[period - 1] = atr;
  for (let i = period; i < len; i++) {
    atr = (atr * (period - 1) + tr[i]) / period;
    res[i] = atr;
  }
  return res;
}
function computeFullAnalysis(candles) {
  if (!candles || candles.length === 0) {
    return { series: {}, summary: null };
  }
  const closes = candles.map((c) => c.close);
  const ema9 = calcEMA(closes, 9);
  const ema21 = calcEMA(closes, 21);
  const sma50 = calcSMA(closes, 50);
  const rsi14 = calcRSI(closes, 14);
  const { macdLine, signalLine, histogram } = calcMACD(closes, 12, 26, 9);
  const bb = calcBollingerBands(closes, 20, 2);
  const atr14 = calcATR(candles, 14);
  const last = candles.length - 1;
  const price = closes[last];
  const curRsi = rsi14[last] ?? 50;
  const curEma9 = ema9[last] ?? price;
  const curEma21 = ema21[last] ?? price;
  const curSma50 = sma50[last] ?? price;
  const curMacd = macdLine[last] ?? 0;
  const curMacdSig = signalLine[last] ?? 0;
  const curHist = histogram[last] ?? 0;
  const prevHist = last > 0 && histogram[last - 1] !== null ? histogram[last - 1] : curHist;
  const curBbUpper = bb.upper[last] ?? price * 1.02;
  const curBbLower = bb.lower[last] ?? price * 0.98;
  const curBbMiddle = bb.middle[last] ?? price;
  const curAtr = atr14[last] ?? price * 8e-3;
  let score = 0;
  const breakdown = {};
  if (curEma9 > curEma21 && price > curEma9) {
    score += 30;
    breakdown.ema = "BULLISH";
  } else if (curEma9 > curEma21) {
    score += 15;
    breakdown.ema = "BULLISH";
  } else if (curEma9 < curEma21 && price < curEma9) {
    score -= 30;
    breakdown.ema = "BEARISH";
  } else {
    score -= 15;
    breakdown.ema = "BEARISH";
  }
  if (price > curSma50) {
    score += 15;
    breakdown.sma50 = "ABOVE";
  } else {
    score -= 15;
    breakdown.sma50 = "BELOW";
  }
  if (curRsi < 30) {
    score += 25;
    breakdown.rsi = "OVERSOLD_BUY";
  } else if (curRsi < 45) {
    score += 10;
    breakdown.rsi = "NEUTRAL_BULL";
  } else if (curRsi > 70) {
    score -= 25;
    breakdown.rsi = "OVERBOUGHT_SELL";
  } else if (curRsi > 58) {
    score += 12;
    breakdown.rsi = "MOMENTUM_BULL";
  } else {
    breakdown.rsi = "NEUTRAL";
  }
  if (curMacd > curMacdSig && curHist > prevHist) {
    score += 20;
    breakdown.macd = "BULLISH_CROSS";
  } else if (curMacd > curMacdSig) {
    score += 10;
    breakdown.macd = "BULLISH";
  } else if (curMacd < curMacdSig && curHist < prevHist) {
    score -= 20;
    breakdown.macd = "BEARISH_CROSS";
  } else {
    score -= 10;
    breakdown.macd = "BEARISH";
  }
  const bbRange = Math.max(curBbUpper - curBbLower, 1e-9);
  const bbPercent = (price - curBbLower) / bbRange;
  if (bbPercent < 0.12) {
    score += 10;
    breakdown.bb = "LOWER_BAND_BOUNCE";
  } else if (bbPercent > 0.88) {
    score -= 10;
    breakdown.bb = "UPPER_BAND_RESIST";
  } else {
    breakdown.bb = "MID_CHANNEL";
  }
  score = Math.max(-100, Math.min(100, Math.round(score)));
  let signal = "NEUTRAL";
  if (score >= 50) signal = "STRONG_BUY";
  else if (score >= 18) signal = "BUY";
  else if (score <= -50) signal = "STRONG_SELL";
  else if (score <= -18) signal = "SELL";
  const mapSeries = (arr) => candles.map((c, idx) => arr[idx] !== null && Number.isFinite(arr[idx]) ? { time: c.time, value: arr[idx] } : null).filter(Boolean);
  return {
    series: {
      ema9: mapSeries(ema9),
      ema21: mapSeries(ema21),
      sma50: mapSeries(sma50),
      rsi14: mapSeries(rsi14),
      macdLine: mapSeries(macdLine),
      signalLine: mapSeries(signalLine),
      histogram: candles.map(
        (c, idx) => histogram[idx] !== null && Number.isFinite(histogram[idx]) ? {
          time: c.time,
          value: histogram[idx],
          color: histogram[idx] >= 0 ? "rgba(16, 185, 129, 0.75)" : "rgba(239, 68, 68, 0.75)"
        } : null
      ).filter(Boolean),
      bbUpper: mapSeries(bb.upper),
      bbMiddle: mapSeries(bb.middle),
      bbLower: mapSeries(bb.lower)
    },
    raw: { ema9, ema21, sma50, rsi14, macdLine, signalLine, histogram, bb, atr14 },
    summary: {
      price,
      rsi14: Number(curRsi.toFixed(2)),
      ema9: curEma9,
      ema21: curEma21,
      sma50: curSma50,
      macd: curMacd,
      macdSignal: curMacdSig,
      macdHist: curHist,
      bbUpper: curBbUpper,
      bbMiddle: curBbMiddle,
      bbLower: curBbLower,
      bbPercent: Number((bbPercent * 100).toFixed(1)),
      atr14: curAtr,
      atrPct: Number((curAtr / price * 100).toFixed(2)),
      score,
      signal,
      breakdown
    }
  };
}

