        this.pushEvent("FUNDING", "Funding charged", "\u0641\u0627\u0646\u062F\u06CC\u0646\u06AF \u06A9\u0633\u0631 \u0634\u062F", `$${total.toFixed(2)} \xB7 ${positions.length} positions`);
