      this.state.equityCurve = [{ time: Math.floor(Date.now() / 1e3), equity: val }];
      this.pushEvent("WARNING", `Account reset to $${val.toLocaleString()}`, `\u062D\u0633\u0627\u0628 \u0645\u0639\u0627\u0645\u0644\u0627\u062A\u06CC \u0628\u0647 \u0645\u0628\u0644\u063A $${val.toLocaleString()} \u0628\u0627\u0632\u0646\u0634\u0627\u0646\u06CC \u0634\u062F`);
