      threshold: Number(cfg.threshold) > 0 ? Number(cfg.threshold) : 0.5,
      effectiveThreshold: guard.effective,
      roundTripCost: guard.cost,
      cooldownSec: Number(cfg.cooldownSec) > 0 ? Number(cfg.cooldownSec) : 60,
      lastRunAt: cfg.lastRunAt || null,
      lastClosedCount: cfg.lastClosedCount || 0,
      lastClosedPnl: cfg.lastClosedPnl || 0,
