      threshold: threshold === void 0 || threshold === null || threshold === "" ? prev.threshold : Math.max(0.01, Math.min(1e5, Number(threshold) || prev.threshold)),
      cooldownSec: cooldownSec === void 0 ? prev.cooldownSec : Math.max(5, Math.min(3600, Number(cooldownSec) || 60)),
