function enforceBotConfig() {
  try {
    const bots = tradingEngine.state?.bots || [];
    let changed = false;
    for (const b of bots) {
      if (b.presetId === "SCALP" || b.presetId === "ALPHA") {
        if (Number(b.cfgRev) !== BOT_CFG.rev) {
          b.cfgRev = BOT_CFG.rev;
          changed = true;
        }
        continue;
      }
      if (Number(b.cfgRev) >= BOT_CFG.rev) continue;
      Object.assign(b, BOT_CFG);
      b.cfgRev = BOT_CFG.rev;
      b.maxSameDirection = Math.max(1, Math.ceil((Number(BOT_CFG.maxOpenPositions) || 10) * 0.6));
      changed = true;
    }
    if (changed) {
      tradingEngine.saveState();
      console.log(`[cfg] bot config locked to rev ${BOT_CFG.rev}`);
    }
    return changed;
  } catch (err) {
    console.log("[cfg] enforce skipped:", err.message);
    return false;
  }
}
