function ensureBalancePlan() {
  try {
    const st = tradingEngine.state;
    if (!st) return;
    if (Number(st.settings?.balancePlanUSD) === BALANCE_PLAN_USD) return;
    const from = Number(st.initialBalance) || 100;
    const delta = Number((BALANCE_PLAN_USD - from).toFixed(2));
    st.initialBalance = BALANCE_PLAN_USD;
    if (delta !== 0) st.balance = Number((Number(st.balance || 0) + delta).toFixed(2));
    st.settings = st.settings || {};
    st.settings.balancePlanUSD = BALANCE_PLAN_USD;
    tradingEngine.saveState();
    try {
      tradingEngine.recordEquitySnapshot();
    } catch {
    }
    console.log(
      `[balance] plan $${from.toFixed(2)} \u2192 $${BALANCE_PLAN_USD.toLocaleString()} (deposit +$${delta.toFixed(2)}, history kept)`
    );
  } catch (err) {
    console.log("[balance] plan skipped:", err.message);
  }
}
